from collections import Counter

def transform(grid):
    all_elements = [cell for row in grid for cell in row]
    bg = Counter(all_elements).most_common(1)[0][0]
    rows = len(grid)
    cols = len(grid[0])

    output = [[bg] * cols for _ in range(rows)]

    for col in range(cols):
        non_bg = []
        for row in range(rows):
            if grid[row][col] != bg:
                non_bg.append(grid[row][col])
        start_row = rows - len(non_bg)
        for i in range(len(non_bg)):
            output[start_row + i][col] = non_bg[i]

    return output

